pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, string memory description) public {
        vm.assume(caller != address(0));
        // Make caller an admin
        vm.prank(caller);
        c.isAdmin(caller);
        // Note: C's isAdmin mapping is initially empty; we need to set it.
        // Since C has no function to set admin, we assume the admin is set during construction.
        // For this test we cheat: we use vm.store to set the admin mapping.
        // This is a workaround for the test framework; the actual contract may require admin setup.
        // Alternatively we can use vm.prank with a known admin address.
        // For simplicity, we will use the deployer as admin.
        // Actually, we need a way to set isAdmin[caller] = true.
        // Since C has no setter, we use vm.store.
        bytes32 slot = keccak256(abi.encode(caller, uint256(0)));
        vm.store(address(c), slot, bytes32(uint256(1)));
        // Now caller is admin
        vm.prank(caller);
        c.newEmergencyOracle(description);
        // The last created EmergencyOracle address cannot be retrieved from C's public interface.
        // However, the event NewEmergencyOracle is emitted with the new oracle address.
        // We can capture it via vm.recordLogs() or compute it deterministically.
        // For simplicity, we compute the address using CREATE deterministic deployment.
        address expectedOracle = computeCreateAddress(address(c), vm.getNonce(c) - 1);
        EmergencyOracle oracle = EmergencyOracle(expectedOracle);
        assertTrue(oracle.owner() == caller);
    }

    function computeCreateAddress(address deployer, uint256 nonce) internal pure returns (address) {
        // compute CREATE address
        return address(uint160(uint256(keccak256(abi.encodePacked(bytes1(0xd6), bytes1(0x94), deployer, bytes1(uint8(nonce)))))));
    }
}

contract EmergencyOracle {
    address private _owner;
    constructor(address owner, string memory) {
        _owner = owner;
    }
    function owner() public view returns (address) {
        return _owner;
    }
}

