import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address admin, string calldata description) public {
        vm.assume(admin != address(0));
        vm.prank(admin);
        c.newEmergencyOracle(description);
        assertTrue(c.newEmergencyOracle() != address(0));
    }
}
